namespace sv_ec508a3bc6cd40a887a648250f0fd249.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors = new()
    {
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Patel",
        "Dr. Williams"
    };

    private static readonly Dictionary<string, List<string>> DoctorSlots = new()
    {
        ["Dr. Smith"] = new() { "9:00 AM", "10:00 AM", "11:00 AM", "2:00 PM", "3:00 PM" },
        ["Dr. Johnson"] = new() { "8:00 AM", "10:00 AM", "1:00 PM", "4:00 PM" },
        ["Dr. Patel"] = new() { "9:00 AM", "10:30 AM", "11:30 AM", "2:30 PM" },
        ["Dr. Williams"] = new() { "8:30 AM", "10:00 AM", "12:00 PM", "3:30 PM" }
    };

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableSlotsAsync(string doctor, DateOnly date)
    {
        if (DoctorSlots.TryGetValue(doctor, out var slots))
        {
            return Task.FromResult(slots);
        }
        return Task.FromResult(new List<string>());
    }

    /// <summary>
    /// Validates patient/appointment data against server-side business rules.
    /// Returns a dictionary of field name → error messages.
    /// </summary>
    public Task<Dictionary<string, List<string>>> ValidatePatientAsync(
        string email, string insuranceProvider, string doctor, string timeSlot)
    {
        var errors = new Dictionary<string, List<string>>();

        // Reject email with outstanding balance
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(AppointmentModel.Email)] = new() { "Account has outstanding balance" };
        }

        // Reject "None" insurance with Dr. Smith (doesn't accept self-pay)
        if (insuranceProvider == "None" && doctor == "Dr. Smith")
        {
            errors[nameof(AppointmentModel.Doctor)] = new() { "Selected doctor does not accept self-pay patients" };
        }

        // Reject 10:00 AM slot as taken (simulates race condition)
        if (timeSlot == "10:00 AM")
        {
            errors[nameof(AppointmentModel.TimeSlot)] = new() { "This slot is no longer available" };
        }

        return Task.FromResult(errors);
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_ec508a3bc6cd40a887a648250f0fd249.Services;

public class AppointmentModel
{
    // Step 1
    [Required(ErrorMessage = "Patient name is required.")]
    public string? PatientName { get; set; }

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Invalid email format.")]
    public string? Email { get; set; }

    [Required(ErrorMessage = "Phone number is required.")]
    public string? Phone { get; set; }

    [Required(ErrorMessage = "Insurance provider is required.")]
    public string? InsuranceProvider { get; set; }

    // Step 2
    [Required(ErrorMessage = "Please select a doctor.")]
    public string? Doctor { get; set; }

    [Required(ErrorMessage = "Appointment date is required.")]
    public DateOnly? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Please select a time slot.")]
    public string? TimeSlot { get; set; }

    [Required(ErrorMessage = "Reason for visit is required.")]
    [MaxLength(500, ErrorMessage = "Reason cannot exceed 500 characters.")]
    public string? ReasonForVisit { get; set; }
}

public class FutureDateAttribute : ValidationAttribute
{
    protected override ValidationResult? IsValid(object? value, ValidationContext validationContext)
    {
        if (value is DateOnly date && date <= DateOnly.FromDateTime(DateTime.Today))
        {
            return new ValidationResult("Appointment date must be in the future.");
        }
        return ValidationResult.Success;
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_ec508a3bc6cd40a887a648250f0fd249.Services
@inject AppointmentService AppointmentService

<h3>Book an Appointment</h3>

<EditForm EditContext="editContext" OnValidSubmit="HandleSubmit" FormName="book-appointment">
    <DataAnnotationsValidator />
    <CustomValidator @ref="customValidator" />

    @* STEP 1 *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label">Patient Name</label>
            <InputText class="form-control" @bind-Value="model.PatientName" />
            <ValidationMessage For="() => model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label">Email</label>
            <InputText class="form-control" @bind-Value="model.Email" />
            <ValidationMessage For="() => model.Email" />
        </div>

        <div class="mb-3">
            <label class="form-label">Phone</label>
            <InputText class="form-control" @bind-Value="model.Phone" />
            <ValidationMessage For="() => model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label">Insurance Provider</label>
            <InputSelect class="form-select" @bind-Value="model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                Next
            </button>
        }
    </fieldset>

    @* STEP 2 *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label">Preferred Doctor</label>
                <InputSelect class="form-select" @bind-Value="model.Doctor" @bind:after="OnDoctorChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.Doctor" />
            </div>

            <div class="mb-3">
                <label class="form-label">Date</label>
                <InputDate class="form-control" @bind-Value="model.AppointmentDate" @bind:after="OnDateChanged" />
                <ValidationMessage For="() => model.AppointmentDate" />
                @if (model.AppointmentDate.HasValue && model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
                {
                    <div class="text-danger">Appointment date must be in the future.</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label">Time Slot</label>
                <InputSelect class="form-select" @bind-Value="model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.TimeSlot" />
            </div>

            <div class="mb-3">
                <label class="form-label">Reason for Visit</label>
                <InputTextArea class="form-control" @bind-Value="model.ReasonForVisit" rows="3" />
                <ValidationMessage For="() => model.ReasonForVisit" />
            </div>

            <button type="button" class="btn btn-secondary me-2" @onclick="CheckAvailability" disabled="@isSubmitting">
                @(isSubmitting ? "Checking..." : "Check Availability")
            </button>

            @if (availabilityChecked && !hasServerErrors)
            {
                <button type="submit" class="btn btn-success" disabled="@isSubmitting">
                    Book Appointment
                </button>
            }
        </fieldset>
    }

    @if (isBooked)
    {
        <div class="alert alert-success mt-3">Appointment booked successfully!</div>
    }
</EditForm>

@code {
    private AppointmentModel model = new();
    private EditContext editContext = default!;
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isSubmitting;
    private bool isBooked;
    private bool availabilityChecked;
    private bool hasServerErrors;

    private List<string> doctors = new();
    private List<string> availableSlots = new();

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate step 1 fields only
        var step1Valid = true;
        var step1Fields = new[] {
            nameof(AppointmentModel.PatientName),
            nameof(AppointmentModel.Email),
            nameof(AppointmentModel.Phone),
            nameof(AppointmentModel.InsuranceProvider)
        };

        foreach (var field in step1Fields)
        {
            var fi = editContext.Field(field);
            editContext.NotifyFieldChanged(fi);
        }

        editContext.Validate();

        foreach (var field in step1Fields)
        {
            var fi = editContext.Field(field);
            if (editContext.GetValidationMessages(fi).Any())
            {
                step1Valid = false;
                break;
            }
        }

        if (step1Valid)
        {
            showStep2 = true;
        }
    }

    private async Task OnDoctorChanged()
    {
        availableSlots = new();
        model.TimeSlot = null;
        availabilityChecked = false;

        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                model.Doctor, model.AppointmentDate.Value);
        }
    }

    private async Task OnDateChanged()
    {
        availableSlots = new();
        model.TimeSlot = null;
        availabilityChecked = false;

        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                model.Doctor, model.AppointmentDate.Value);
        }
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();
        availabilityChecked = false;
        hasServerErrors = false;

        // Validate date is in the future
        if (model.AppointmentDate.HasValue && model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            return;
        }

        // Validate step 2 fields
        editContext.Validate();
        var step2Fields = new[] {
            nameof(AppointmentModel.Doctor),
            nameof(AppointmentModel.AppointmentDate),
            nameof(AppointmentModel.TimeSlot),
            nameof(AppointmentModel.ReasonForVisit)
        };

        foreach (var field in step2Fields)
        {
            var fi = editContext.Field(field);
            if (editContext.GetValidationMessages(fi).Any())
            {
                return;
            }
        }

        isSubmitting = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                model.Email!, model.InsuranceProvider!, model.Doctor!, model.TimeSlot!);

            if (errors.Count > 0)
            {
                customValidator!.DisplayErrors(errors);
                hasServerErrors = true;
            }

            availabilityChecked = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private async Task HandleSubmit()
    {
        // Final submission — appointment is booked
        isBooked = true;
        await Task.CompletedTask;
    }
}

@using Microsoft.AspNetCore.Components.Forms

@code {
    [CascadingParameter]
    private EditContext? EditContext { get; set; }

    private ValidationMessageStore? messageStore;

    protected override void OnInitialized()
    {
        if (EditContext is null)
            throw new InvalidOperationException("CustomValidator requires a cascading EditContext.");

        messageStore = new ValidationMessageStore(EditContext);
        EditContext.OnValidationRequested += (s, e) => messageStore.Clear();
        EditContext.OnFieldChanged += (s, e) => messageStore.Clear(e.FieldIdentifier);
    }

    public void DisplayErrors(Dictionary<string, List<string>> errors)
    {
        foreach (var (field, messages) in errors)
        {
            foreach (var message in messages)
            {
                messageStore!.Add(EditContext!.Field(field), message);
            }
        }
        EditContext!.NotifyValidationStateChanged();
    }

    public void ClearErrors()
    {
        messageStore?.Clear();
        EditContext?.NotifyValidationStateChanged();
    }
}

